@dataclass
class TestCase:
    """단일 테스트 케이스"""

    name: str
    description: str
    inputs: dict[str, Any]
    expected: Any
    raises: type[Exception] | None = None
    marks: list[str] = field(default_factory=list)  # pytest.mark.xxx
    fixtures: list[str] = field(default_factory=list)


@dataclass
class ParameterizedTest:
    """파라미터화된 테스트"""

    function_name: str
    params: list[str]  # 파라미터 이름들
    test_cases: list[TestCase]
    fixture_deps: list[str] = field(default_factory=list)


@dataclass
class MockSpec:
    """목 사양"""

    target: str  # 모킹할 대상 (예: "httpx.AsyncClient.get")
    return_value: Any = None
    side_effect: Any = None
    spec: Any = None
    autospec: bool = False


@dataclass
class GeneratedTestModule:
    """생성된 테스트 모듈"""

    source_file: str
    test_file: str
    imports: list[str]
    fixtures: list[str]
    test_functions: list[str]
    parameterized_tests: list[ParameterizedTest]
    mocks: list[MockSpec]
    coverage_targets: list[str] = field(default_factory=list)


