    @_mutmut_mutated(mutants_xǁTestGeneratorǁ_render_test_module__mutmut)
    def _render_test_module(self, module: GeneratedTestModule) -> str:
        """테스트 모듈 코드 렌더링"""
        lines = [
            '"""',
            f"Auto-generated tests for {module.source_file}",
            '"""',
            "",
        ]

        # Imports
        for imp in module.imports:
            lines.append(imp)
        lines.append("")

        # Fixtures
        for fixture in module.fixtures:
            lines.append(fixture)
            lines.append("")

        # Test functions
        for test_func in module.test_functions:
            lines.append(test_func)
            lines.append("")

        return "\n".join(lines)

